# Read the assistant messages that contain toolCall
grep '"toolCall"' .state/sessions/history/s_1774132617492_345/session.jsonl | head -10 | python3 -c "
import sys, json
for line in sys.stdin:
    data = json.loads(line.strip())
    if 'content' in data:
        for item in data['content']:
            if item.get('type') == 'toolCall':
                name = item.get('name','')
                args = item.get('arguments',{})
